import { Button } from "@/registry/erbium/ui/button";

export default function SpinnerButton() {
  return (
    <div className="flex flex-col items-center gap-group">
      <Button loading size="sm">
        Loading...
      </Button>
      <Button variant="outline" loading size="sm">
        Please wait
      </Button>
      <Button variant="secondary" loading size="sm">
        Processing
      </Button>
    </div>
  );
}

import ExampleSpinnerButton from "../examples/spinner-button";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleSpinnerButton />
  </div>
);

export default Example;
